#!/usr/bin/env bash
# Personal cloud skills, exported 2026-10-02. Bash and Python 3.10+ only.
# Paste this entire script into a cloud environment Install script, after
# repository checkout. No download, token, or uploaded attachment is needed.
# Default: install into the current user's standard ~/.agents/skills directory.
# Explicit use: bash install-cloud-skills.sh --target /absolute/repo/.agents/skills
# Inspect without writing: append --dry-run. Verify only: --verify-only.
# Conflicting existing skills are preserved; installation stops for review.
set -euo pipefail
python3 - "$@" <<'PERSONAL_CLOUD_SKILLS_PY'
