if hashlib.sha256(payload).hexdigest() != '07965a73fbc401bb0d4b9c19605f49524400df51a8ea88b6f75b68b031bcc327':
    raise SystemExit('Embedded skills checksum mismatch')
args = sys.argv[1:]
if not any(flag in args for flag in ("--target", "--user", "--list", "--verify-only")):
    args = ["--user", *args]
with tempfile.TemporaryDirectory(prefix='personal-cloud-skills-') as raw:
    bundle = Path(raw)
    with tarfile.open(fileobj=io.BytesIO(payload), mode='r:gz') as archive:
        for member in archive.getmembers():
            path = Path(member.name)
            if not member.isfile() or path.is_absolute() or '..' in path.parts:
                raise SystemExit('Unsafe embedded archive member')
            destination = bundle / path
            destination.parent.mkdir(parents=True, exist_ok=True)
            with archive.extractfile(member) as stream:
                destination.write_bytes(stream.read())
    command = [sys.executable, str(bundle / 'install.py')]
    if '--target' in args or '--user' in args or '--list' in args or '--verify-only' in args:
        subprocess.run(command + args, check=True)
    else:
        roots = []
        for current, dirs, names in os.walk('/workspace', followlinks=False):
            directory = Path(current)
            metadata = directory / '.git'
            if metadata.exists() and not (metadata.is_dir() and not any(metadata.iterdir())):
                result = subprocess.run(['git', '-C', current, 'rev-parse', '--show-toplevel'], capture_output=True, text=True, check=True)
                root = Path(result.stdout.strip()).resolve()
                if not root.is_relative_to(Path('/workspace')):
                    raise SystemExit('Checkout escapes /workspace')
                if root not in roots:
                    roots.append(root)
                dirs[:] = []
            else:
                dirs[:] = [d for d in dirs if not d.startswith('.') and d not in {'node_modules', 'target', 'attachments', 'skill-bundles', 'cloud-skill-kit'}]
        if not roots:
            raise SystemExit('No Git checkout found. Pass --target /absolute/repo/.agents/skills.')
        # Check every target before writing to any repository.
        for root in roots:
            subprocess.run(command + ['--target', str(root / '.agents/skills'), '--dry-run'] + args, check=True)
        if '--dry-run' not in args:
            for root in roots:
                subprocess.run(command + ['--target', str(root / '.agents/skills')] + args, check=True)
PERSONAL_CLOUD_SKILLS_PY
